+    private final ValueFetcher fetcher;
+    private final LeafStoredFieldLoader loader;
+    private final List<Object> ignoredValues = new ArrayList<>();
+    private int docID = -1;
+
+    BlockSourceReader(ValueFetcher fetcher, LeafStoredFieldLoader loader) {
+        this.fetcher = fetcher;
+        this.loader = loader;
+    }
+
+    @Override
+    public BlockLoader.Builder readValues(BlockLoader.BuilderFactory factory, BlockLoader.Docs docs) throws IOException {
+        BlockLoader.Builder blockBuilder = builder(factory, docs.count());
+        for (int i = 0; i < docs.count(); i++) {
+            int doc = docs.get(i);
+            if (doc < this.docID) {
