+public class SingletonOrdinalsBuilder implements BlockLoader.SingletonOrdinalsBuilder, Releasable, Block.Builder {
+    private final BlockFactory blockFactory;
+    private final SortedDocValues docValues;
+    private int[] ords;
+    private int count;
