+            // Increment breaker for sorted ords.
+            blockFactory.adjustBreaker(breakerSize, false);
+            try {
+                int[] sortedOrds = ords.clone();
+                Arrays.sort(sortedOrds);
+                int uniqueCount = compactToUnique(sortedOrds);
